"""Copy the existing static files and Jinja templates into the Worker bundle."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
templates = {
    path.name: path.read_text(encoding="utf-8")
    for path in sorted((ROOT / "templates").glob("*.html"))
}
(ROOT / "src" / "worker_templates.py").write_text(
    "# Generated by tools/package_worker.py; edit templates/ instead.\n"
    "import json\n\nTEMPLATES = json.loads(" + repr(json.dumps(templates, ensure_ascii=False)) + ")\n",
    encoding="utf-8",
)

public = ROOT / "public"
static_target = public / "static"
if static_target.exists():
    import shutil

    shutil.rmtree(static_target)
static_target.parent.mkdir(parents=True, exist_ok=True)
import shutil

shutil.copytree(ROOT / "static", static_target)
print("Worker templates and static assets are ready.")
